-- Seed the authoritative asset register from Asset List .pdf (71 footbridges + 9 subways).
-- Run after production-upgrade.sql. Matching uses Field ID; unconfirmed GIS elements remain unlinked.
on conflict(asset_key) do update set asset_name=excluded.asset_name,asset_type=excluded.asset_type,field_id=excluded.field_id,asset_ref_id=excluded.asset_ref_id,latitude=excluded.latitude,longitude=excluded.longitude,source_data=excluded.source_data,updated_at=now();

-- Link imported and user-created project rows to assets only where Field ID exactly matches the authoritative asset Field ID.
update public.project_records r set asset_id=a.id from public.assets a where r.asset_id is null and nullif(trim(r.data->>'Field ID'),'') is not null and lower(trim(r.data->>'Field ID'))=lower(trim(a.field_id));
